def mystery(container):
    result = []
    for i in range(len(container)):
        if i % 2 == 0:
            result.append(container[i] * 2)
        else:
            result.append(container[i] + 3)
    return result

def mystery(container):
    result = []
    for i in range(len(container)):
        if i % 2 != 0:
            result.append(container[i] * 4)
        else:
            result.append(container[i] * (-1))
    return result
